python3 -c "
import sys, os
print(sys.version)
print('--- site-packages ---')
for p in sys.path:
    if os.path.isdir(p):
        try:
            items = sorted(os.listdir(p))
            hits = [i for i in items if 'openpyxl' in i or 'xlrd' in i or 'xlsx' in i.lower()]
            if hits:
                print(p, hits)
        except Exception:
            pass
